const inputData = items[0].json;
const orders = inputData.orders || [];

// 1. Tính batchRequestTime (thời gian hiện tại UTC milliseconds)
const batchRequestTime = Date.now();

// 2. Hàm tạo chuỗi ngẫu nhiên an toàn không cần dùng thư viện crypto
function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

// Tạo batchRequestId duy nhất trong ngày cho thao tác đặt lệnh (BUY)
const today = new Date().toISOString().slice(0, 10).replace(/-/g, '');
const batchRequestId = `BUY_${today}_${generateUUID()}`;

// Gắn các tham số bảo mật và chống trùng lặp vào payload gửi đi
const payload = {
  batchRequestId: batchRequestId,
  batchRequestTime: batchRequestTime,
  orders: orders
};

return [{ 
  json: {
    body: payload,
    accessToken: inputData.accessToken
  }
}];

const crypto = require('crypto');

const inputData = items[0].json.body;
const accessToken = items[0].json.accessToken;

const secret = $env.SSI_API_SECRET;
const rawKey = ($env.SSI_PRIVATE_KEY || '').trim();
if (!secret || !rawKey) {
  throw new Error('Missing env SSI_API_SECRET or SSI_PRIVATE_KEY');
}

// Accepts PEM ("-----BEGIN ...", \n allowed) or the base64-encoded <RSAKeyValue> XML from the SSI portal
function loadPrivateKey(raw) {
  if (raw.includes('BEGIN')) {
    return crypto.createPrivateKey(raw.replace(/\\n/g, '\n'));
  }
  const xml = Buffer.from(raw, 'base64').toString('utf8');
  const get = (tag) => {
    const m = xml.match(new RegExp('<' + tag + '>([^<]+)</' + tag + '>'));
    if (!m) throw new Error('RSAKeyValue is missing <' + tag + '>');
    return Buffer.from(m[1], 'base64').toString('base64url');
  };
  return crypto.createPrivateKey({
    key: {
      kty: 'RSA',
      n: get('Modulus'), e: get('Exponent'), d: get('D'),
      p: get('P'), q: get('Q'), dp: get('DP'), dq: get('DQ'), qi: get('InverseQ'),
    },
    format: 'jwk',
  });
}

// The exact string signed is the exact string sent (Place Orders sends bodyString as raw body).
const bodyString = JSON.stringify(inputData);

// SSI spec: X-Signature = RSA-SHA256( SecretKey + JSON body ), base64
const sign = crypto.createSign('RSA-SHA256');
sign.update(bodyString);
sign.end();
const signature = sign.sign(loadPrivateKey(rawKey), 'hex');

return [{ json: { accessToken, bodyString, signature } }];
